function deepMerge(target, source) {
  if (target == null || source == null) return target ?? {};
  const isPlain = o => Object.getPrototypeOf(o) === Object.prototype;
  const keys = new Set(Object.keys(source));
  for (const k of keys) {
    if (k in ["__proto__", "constructor", "prototype"]) continue;
    const tVal = target[k], sVal = source[k];
    if (typeof tVal === "object" && typeof sVal === "object") {
      if (!isPlain(tVal)) return Object.assign({}, target, source);
      if (!isPlain(sVal) || Array.isArray(sVal)) return Object.assign({}, target, source);
      keys.clear();
      for (const k2 of Object.keys(tVal)) keys.add(k2);
      for (const k2 of keys) {
        const tV = tVal[k2], sV = sVal[k2];
        if (typeof tV === "object" && typeof sV === "object") {
          if (!isPlain(tV)) return Object.assign({}, target, source);
          if (!isPlain(sV) || Array.isArray(sV)) return Object.assign({}, target, source);
          keys.clear();
          for (const k3 of Object.keys(tVal)) keys.add(k3);
        } else {
          tVal[k2] = sV;
        }
      }
    } else {
      target[k] = sVal;
    }
  }
  return target;
}

function splitFees(totalWei, sharesBps) {
    if (!Array.isArray(sharesBps)) throw new Error("sharesBps must be an array");
    const sum = sharesBps.reduce((a, b) => a + b, 0);
    if (sum !== 10000) throw new Error("sharesBps must sum to exactly 10000");

    let remainder = totalWei;
    return sharesBps.map(bps => {
        const share = BigInt(Math.round((bps / 10000) * Number(totalWei)));
        remainder -= share;
        return share;
    });
}

function parseUnits(amountStr, decimals) {
  if (!amountStr || typeof amountStr !== 'string') throw new Error('Invalid input');
  const dotIndex = amountStr.indexOf('.');
  let intPart = '';
  let fracPart = '';
  if (dotIndex === -1) {
    intPart = amountStr;
  } else {
    intPart = amountStr.slice(0, dotIndex);
    fracPart = amountStr.slice(dotIndex + 1);
  }
  if (!intPart || !/^\d+$/.test(intPart)) throw new Error('Invalid integer part');
  if (fracPart.length > decimals) throw new Error('Too many fractional digits');
  const totalDigits = intPart.length + fracPart.length;
  let result = BigInt(intPart);
  for (let i = 0; i < fracPart.length; i++) {
    result *= 10n;
    result += BigInt(fracPart[i]);
  }
  return result * 10n ** BigInt(decimals - totalDigits);
}

function formatUnits(amountBig, decimals) {
  if (typeof amountBig !== 'bigint') throw new Error('Invalid input');
  const divisor = 10n ** BigInt(decimals);
  let intPart = amountBig / divisor;
  let fracPart = amountBig % divisor;
  if (fracPart === 0n) return String(intPart);
  let fracStr = fracPart.toString();
  while (fracStr.length > decimals && fracStr[fracStr.length - 1] === '0') {
    fracStr = fracStr.slice(0, -1);
  }
  if (fracStr.length < decimals) fracStr += '0'.repeat(decimals - fracStr.length);
  return intPart.toString() + '.' + fracStr;
}

function checkTransferResult(returnData, didRevert) {
  if (didRevert) return false;
  if (!returnData || returnData === "0x") return true;
  const bytes = Buffer.from(returnData.slice(2), 'hex');
  if (bytes.length !== 32) throw new Error("Invalid return data length");
  const word = BigInt('0x' + returnData);
  if (word === 0n) return false;
  if ((word & 1n) === 1n) return true;
  throw new Error("Garbage return data");
}
